(function(){
'use strict';
const KEY='nawaf-hq-v5';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'smart-command'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function toast(text){const x=document.querySelector('.toast');if(!x)return;x.textContent=text;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),2800)}
function ensureWorkers(s){s.employees=Array.isArray(s.employees)?s.employees:[];const add=e=>{if(!s.employees.some(x=>x.id===e.id))s.employees.push(e)};add({id:'fahad',name:'فهد',role:'مهندس البرمجيات والمشاريع',department:'التقنية والتطوير',status:'READY',task:'',permissions:{tasks:true,projects:true,review:true,code:true,deploy:false,external:true}});add({id:'finance',name:'راكان',role:'المحلل المالي والاستثماري',department:'الاستثمار والتحليل المالي',status:'READY',task:'',financeMode:'ANALYZE_ONLY',permissions:{tasks:true,projects:false,review:true,code:false,deploy:false,external:true}});return s}
function namedEmployee(s,text){const q=String(text||'').toLowerCase(),names={sara:['سارة','سارا','sara'],fahad:['فهد','fahad'],omar:['عمر','omar'],noura:['نورة','نورا','noura'],lian:['ليان','lian'],finance:['راكان','rakan']};for(const [id,aliases] of Object.entries(names))if(aliases.some(n=>q.includes(n.toLowerCase())))return (s.employees||[]).find(e=>e.id===id);return null}
function preferredIds(text){const q=String(text||'').toLowerCase();if(/أرامكو|ارامكو|سهم|مالي|استثمار|تقييم|قوائم مالية|valuation|stock|portfolio|earnings/.test(q))return ['finance'];if(/مراجعة|جودة|اختبار|تست|qa|تدقيق/.test(q))return ['noura','sara','omar'];if(/اصلح|أصلح|حسن|حسّن|كود|برمج|تقني|api|ربط|خطأ|bug|backend|frontend|github|vercel/.test(q))return ['fahad','omar','sara','noura'];if(/تصميم|واجهة|تجربة|منتج|ux|ui/.test(q))return ['lian','sara','fahad'];if(/فكرة|بحث|فرصة|اقتراح|استكشف|research/.test(q))return ['omar','sara','ideas'];return ['sara','omar','fahad','lian','noura','finance','ideas']}
function chooseEmployee(s,text,explicit){if(explicit){const x=(s.employees||[]).find(e=>e.id===explicit);if(x)return x}const named=namedEmployee(s,text);if(named)return named;const busy=new Set(['WORKING','RESEARCHING','REVIEWING']);for(const id of preferredIds(text)){const e=(s.employees||[]).find(x=>x.id===id&&!busy.has(x.status));if(e)return e}for(const id of preferredIds(text)){const e=(s.employees||[]).find(x=>x.id===id);if(e)return e}return (s.employees||[])[0]||null}
function detectProject(text,selected=''){if(selected)return selected;const q=String(text||'').toLowerCase();if(/مُ?عِين|mueen/.test(q))return 'mueen';if(/قدّ?ها|qaddha/.test(q))return 'qaddha';return ''}
async function push(){try{if(window.HQCloudReady)await window.HQCloudReady;if(window.HQCloud?.push)await window.HQCloud.push()}catch{}}
function smartModal(){let m=document.getElementById('smart-command-modal');if(!m){m=document.createElement('div');m.id='smart-command-modal';m.className='v8-modal';m.innerHTML='<div class="v8-dialog"><div id="smart-command-dialog"></div></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m)closeModal()})}return {m,d:m.querySelector('#smart-command-dialog')}}
function closeModal(){document.getElementById('smart-command-modal')?.classList.remove('show')}
function open(){
 const s=ensureWorkers(read()),{m,d}=smartModal();write(s,'ensure-real-workers');
 const projects=s.projects||[],employees=s.employees||[];
 d.innerHTML=`<div class="v8-dialog-head"><div><span class="v8-kicker">SMART COMMAND</span><h2>توجيه الشركة الذكي</h2><small>اكتب المطلوب فقط، والنظام يختار الموظف والمشروع ومسار التنفيذ.</small></div><button class="v8-close" type="button" id="smart-command-cancel">×</button></div><form class="v8-form" id="smart-command-form"><label class="full">وش تبغى الشركة تسوي؟<textarea id="smart-command-text" name="command" rows="5" placeholder="مثال: فهد، راجع مُعِين وأصلح المشكلة ثم احفظ الأدلة" required></textarea></label><label>المشروع<select name="projectId"><option value="">تلقائي / عام</option>${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>الإسناد<select name="employeeId"><option value="">ذكي — اختر الأنسب تلقائيًا</option>${employees.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}</select></label><label class="full" style="flex-direction:row;align-items:center"><input type="checkbox" name="runNow" checked style="width:auto;min-height:auto"> شغّل الموظف مباشرة بعد إنشاء المهمة</label><div class="full v8-modal-actions"><button type="button" class="v8-btn" data-smart-cancel>إلغاء</button><button type="submit" class="v8-btn primary">✦ نفّذ التوجيه</button></div></form>`;
 m.classList.add('show');document.getElementById('smart-command-cancel').onclick=closeModal;d.querySelector('[data-smart-cancel]').onclick=closeModal;
 const f=document.getElementById('smart-command-form');f.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(f),command=String(fd.get('command')||'').trim();if(!command)return;const state=ensureWorkers(read()),emp=chooseEmployee(state,command,String(fd.get('employeeId')||''));if(!emp){toast('ما فيه موظف AI متاح حاليًا.');return}const projectId=detectProject(command,String(fd.get('projectId')||'')),isFinance=emp.id==='finance',ts=new Date().toISOString(),task={id:uid('cmd'),title:command,details:command,projectId,employeeId:emp.id,status:'READY',progress:0,createdAt:ts,updatedAt:ts,kind:isFinance?'RESEARCH':'CEO_COMMAND',domain:isFinance?'FINANCE':projectId?'PROJECT':'GENERAL',routing:{employee:emp.id,project:projectId||null,route:isFinance?'FINANCE':projectId?'PROJECT_EXECUTION':'GENERAL_AI',decidedAt:ts}};state.tasks=Array.isArray(state.tasks)?state.tasks:[];state.tasks.unshift(task);emp.status='READY';emp.task=task.title;emp.updatedAt=ts;state.activity=Array.isArray(state.activity)?state.activity:[];state.activity.unshift({id:uid('a'),text:`توجيه مباشر من نواف إلى ${emp.name}: ${task.title}`,type:'REAL',at:ts,updatedAt:ts});state.activity=state.activity.slice(0,120);write(state,'ceo-smart-command');await push();window.NawafHQ3D?.routeEmployee?.(emp.id,'READY');closeModal();const runNow=fd.get('runNow')==='on';toast(`تم إسناد التوجيه إلى ${emp.name}${runNow?' وبدأ التنفيذ':''}`);if(runNow&&window.NawafAgents?.runTask)setTimeout(()=>window.NawafAgents.runTask(task.id),260);else document.querySelector('[data-view="tasks"]')?.click()}
}
function intercept(e){const b=e.target.closest('[data-action="company-command"],#company-command');if(!b)return;e.preventDefault();e.stopImmediatePropagation();open()}
document.addEventListener('click',intercept,true);
window.NawafSmartCommand={open,chooseEmployee,detectProject};
})();
